(26, 1, '2024-11-01 22:04:25', '2024-11-01 22:04:25', '<!-- wp:carbon-fields/service-main-screen {\"data\":{\"dolphincargo_service_main_screen_title\":\"МОРСЬКА ДОСТАВКА ВАНТАЖІВ З КИТАЮ В УКРАЇНУ\",\"dolphincargo_service_main_screen_who_are_we\":\"Надійно, вчасно та безпечно\",\"dolphincargo_service_main-screen_image\":\"http://dolphincargo.loc/wp-content/uploads/2024/11/service-1-main-bg.png\"}} /-->\n\n<!-- wp:carbon-fields/our-achievement {\"data\":{\"dolphincargo_achievement_image\":159,\"dolphincargo_achievement_main\":\"3536 \",\"dolphincargo_achievement_description\":\"вантажів доставили морем  за 2024 рік\",\"dolphincargo_achievement_list\":[{\"_id\":\"cf-AD2NYI1NbyOWatBXMj_u0\",\"_type\":\"_\",\"name\":\"Повний спектр послуг \",\"description\":\"\\u003cp\\u003eМи пропонуємо морську доставку з Китаю, митне оформлення вантажів та всіх необхідних документів.\\u003c/p\\u003e\"},{\"_id\":\"cf-xbf5iOSRToSR0DhbrGnKi\",\"_type\":\"_\",\"name\":\"100% професіоналізм \",\"description\":\"\\u003cp\\u003eМи працюємо без посередників, тому відповідаємо за кожен етап. Маємо власні склади у ключових транспортних вузлах: Китай, ЄС, Україна.\\u003c/p\\u003e\"}]}} /-->\n\n<!-- wp:carbon-fields/warrantyservices {\"data\":{\"dolphincargo_warranty_title\":\"НАШІ послуги\",\"dolphincargo_warranty_list\":[{\"_id\":\"cf-RYgYhqruFPhGqWtvyH4G4\",\"_type\":\"_\",\"name\":\"Морська доставка вантажів з Китаю\",\"image\":164},{\"_id\":\"cf-WQVbGENz8TvhKPwnekRQL\",\"_type\":\"_\",\"name\":\"Доставка збірних вантажів з Китаю морем\",\"image\":163},{\"_id\":\"cf-u_1vKxpaoccSUKM3GXBav\",\"_type\":\"_\",\"name\":\"Склади в Китаї, Європі, Україні для зберігання товарів\",\"image\":162},{\"_id\":\"cf-yxbvHwtOuTHHogXaOzJsP\",\"_type\":\"_\",\"name\":\"Повний супровід та оформлення документів\",\"image\":161}],\"dolphincargo_warranty_logic\":\"yes\"}} /-->\n\n<!-- wp:carbon-fields/calculate-shipping {\"data\":{\"dolphincargo_calculate_shipping_title\":\"БАЖАЄТЕ РОЗРАХУВАТИ ВАРТІСТЬ ДОСТАВКИ? \",\"dolphincargo_calculate_shipping_text\":\"\\u003cp\\u003eНаші менеджери підберуть найкращі індивідуальні рішення для вас та прорахують вартість послуг\\u003c/p\\u003e\",\"dolphincargo_calculate_shipping_image\":167}} /-->\n\n<!-- wp:carbon-fields/delivery-steps {\"data\":{\"dolphincargo_delivery_steps_title\":\"ЯК ПРАЦЮЄ НАША ДОСТАВКА?\",\"dolphincargo_delivery_steps_list\":[{\"_id\":\"cf-fWSbHjMvL19GwDX4H0lf1\",\"_type\":\"_\",\"text\":\"Ви залишаєте заявку на доставку вантажу та обираєте умови перевезення разом з персональним менеджером.\"},{\"_id\":\"cf-16nv0AV1_AkkNrLdY6g3F\",\"_type\":\"_\",\"text\":\"Ваш постачальник відправляє вантаж на наш особистий склад, після його отримання ми готуємо товар до відправлення.\"},{\"_id\":\"cf-yPtJgSomfMqbDFVDmUUgv\",\"_type\":\"_\",\"text\":\"Оформлюємо всі необхідні митні документи для експорту з Китаю.\"},{\"_id\":\"cf-It1NQdyVeYfxhgTWGdqJL\",\"_type\":\"_\",\"text\":\"Наші фахівці завантажують ваш вантаж в збірний контейнер, після чого він відправляється на контейнерне судно.\"},{\"_id\":\"cf-y47uehIqxZrpDZ3Vw2CWu\",\"_type\":\"_\",\"text\":\"Під час перевезення ми тримаємо звʼязок, відстежуємо вантаж та контролюємо графік доставки.\"},{\"_id\":\"cf-5rBvcsZZsiL0CDdakTrHz\",\"_type\":\"_\",\"text\":\"Після прибуття борту до місця призначення, наші спеціалісти проводять митне оформлення вантажу.\"},{\"_id\":\"cf-p6FfIIGsxfCGOZ6klHkaO\",\"_type\":\"_\",\"text\":\"Вантаж доставляється до нашого складу в Одесі, а потім безпосередньо  до необхідного Вам місця призначення.\"}],\"dolphincargo_delivery_steps_road_pic\":164,\"dolphincargo_delivery_steps_transport_pic\":163}} /-->\n\n<!-- wp:carbon-fields/advantages-delivery {\"data\":{\"dolphincargo_advantages_delivery_title\":\"ПЕРЕВАГИ ДОСТАВКИ МОРЕМ\",\"dolphincargo_advantages_delivery_list\":[{\"_id\":\"cf-WmNRLqGLmndUT6JCivdyM\",\"_type\":\"_\",\"icon\":\"\",\"name\":\"Конкурентні ціни.\",\"text\":\"\\u003cp\\u003eЦіна доставки вантажу морем з Китаю значно нижча за інші види транспорту.\\u003c/p\\u003e\"},{\"_id\":\"cf-pqAqSy_712cFsHIhox1oS\",\"_type\":\"_\",\"icon\":\"\",\"name\":\"Надійність.\",\"text\":\"\\u003cp\\u003eМорська доставка – один із найбезпечніших способів транспортування вантажів.\\u003c/p\\u003e\"},{\"_id\":\"cf-TSwGG2bYKaFwB0zBGyU2N\",\"_type\":\"_\",\"icon\":\"\",\"name\":\"Потенціал.\",\"text\":\"\\u003cp\\u003eВи можете доставляти великі обсяги вантажу за один раз.\\u003c/p\\u003e\"}]}} /-->', 'Доставка вантажів із Китаю морем', 'Доставка вантажів з Китаю морем є економним  рішенням перевезення великих обсягів товарів. Ми забезпечимо оптимальні маршрути та вигідні тарифи завдяки налагодженим зв’язкам та досвіду.', 'publish', 'closed', 'closed', '', 'dostavka-vantazhiv-iz-kytayu-morem', '', '', '2024-12-26 09:25:25', '2024-12-26 09:25:25', '', 0, 'http://dolphincargo.loc/?post_type=services&#038;p=26', 0, 'services', '', 0),
(27, 1, '2024-11-01 22:04:48', '2024-11-01 22:04:48', '', 'Авіа доставка вантажів', 'Для термінових та цінних вантажів ми пропонуємо доставку вантажу з Китаю літаком, що забезпечує мінімальний термін доставки, не поступаючись надійності.', 'publish', 'closed', 'closed', '', 'avia-dostavka-vantazhiv', '', '', '2024-12-12 15:16:34', '2024-12-12 15:16:34', '', 0, 'http://dolphincargo.loc/?post_type=services&#038;p=27', 0, 'services', '', 0),
(28, 1, '2024-11-01 22:04:59', '2024-11-01 22:04:59', '', 'Доставка вантажів залізничним транспортом', 'Залізнична доставка з Китаю та Європи – баланс між швидкістю та вартістю. Ми гарантуємо безпеку ваших вантажів та контроль на кожному етапі транспортування. ', 'publish', 'closed', 'closed', '', 'dostavka-vantazhiv-zaliznychnym-transportom', '', '', '2024-12-12 15:16:07', '2024-12-12 15:16:07', '', 0, 'http://dolphincargo.loc/?post_type=services&#038;p=28', 0, 'services', '', 0),
(29, 1, '2024-11-01 22:05:16', '2024-11-01 22:05:16', '', 'Митне оформлення вантажів', 'Ми допоможемо підготувати всю необхідну документацію, заповнити декларації та уникнути можливих проблем із митними органами. Наші експерти гарантують мінімальні терміни проходження митниці.', 'publish', 'closed', 'closed', '', 'mytne-oformlennya-vantazhiv', '', '', '2024-12-12 15:15:32', '2024-12-12 15:15:32', '', 0, 'http://dolphincargo.loc/?post_type=services&#038;p=29', 0, 'services', '', 0),
(30, 1, '2024-11-01 22:05:34', '2024-11-01 22:05:34', '', 'Пошук та викуп товару в Китаї', 'Ми співпрацюємо з великою кількістю надійних виробників, що дозволяє забезпечити пошук необхідних товарів. Завдяки нашому досвіду ви зможете уникнути ризиків, пов’язаних із замовленням продукції з-за кордону.', 'publish', 'closed', 'closed', '', 'poshuk-ta-vykup-tovaru-v-kytayi', '', '', '2024-12-12 15:15:02', '2024-12-12 15:15:02', '', 0, 'http://dolphincargo.loc/?post_type=services&#038;p=30', 0, 'services', '', 0),
(31, 1, '2024-11-01 22:05:56', '2024-11-01 22:05:56', '', 'Доставка вантажів з Китаю під ключ', 'Доставка вантажу з контролем професіоналів на кожному з етапів: від пошуку товарів до отримання вами необхідного вантажу. Ми беремо на себе всю роботу, щоб ваш вантаж прибув точно в термін і без зайвого клопоту.', 'publish', 'closed', 'closed', '', 'dostavka-vantazhiv-z-kytayu-pid-klyuch', '', '', '2024-12-12 15:14:53', '2024-12-12 15:14:53', '', 0, 'http://dolphincargo.loc/?post_type=services&#038;p=31', 0, 'services', '', 0),
