sportation \\u0026 logistics company DOLPHIN CARGO\"}} /-->\n\n<!-- wp:carbon-fields/airplane-call-to-action {\"data\":{\"dolphincargo_home_call_to_title\":\"НЕ МОЖЕТЕ ВИЗНАЧИТИСЬ З ОПТИМАЛЬНИМ ВАРІАНТОМ ПЕРЕВЕЗЕННЯ? \",\"dolphincargo_home_call_to_text\":\"\\u003cp\\u003eНаші менеджери підберуть найкращі індивідуальні рішення саме під запити вашого бізнесу\\u003c/p\\u003e\",\"dolphincargo_home_call_to_image\":98}} /-->\n\n<!-- wp:carbon-fields/about-us {\"data\":{\"dolphincargo_block_about_us_title\":\"ПЕРЕВІРЕНІ ЧАСОМ —  НАВЧЕНІ ДОСВІДОМ\",\"dolphincargo_block_about_us_text\":\"\\u003cp\\u003eDolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів.\\u003c/p\\u003e\\n\\u003cp\\u003e\\u003cbr /\\u003eМи беремо на себе вирішення всіх питань сторони логістики, організації та документообігу транспортування вантажів.\\u003c/p\\u003e\",\"dolphincargo_block_about_us_gallery\":[{\"_id\":\"cf-zFnEoB9KIeuYXu3esS1hJ\",\"_type\":\"_\",\"image\":112},{\"_id\":\"cf-r63llcq5oX7hB8PJ4HFn8\",\"_type\":\"_\",\"image\":111},{\"_id\":\"cf-eIhMDcuPRXMdVCaflThgx\",\"_type\":\"_\",\"image\":110}],\"dolphincargo_block_about_us_link\":[{\"id\":16,\"type\":\"post\",\"subtype\":\"page\"}]}} /-->\n\n<!-- wp:carbon-fields/advantages {\"data\":{\"dolphincargo_block_advantages_title\":\"ВАШ НАДІЙНИЙ ПАРТНЕР \\u003c/br\\u003e З ВАНТАЖОПЕРЕВЕЗЕНЬ\",\"dolphincargo_block_advantages_list\":[{\"_id\":\"cf-6CfizFOUrlPc6JAPMwq42\",\"_type\":\"_\",\"name\":\"Маємо власні склади у ключових транспортних вузлах: Китай, ЄС, Україна\",\"description\":\"\\u003cp\\u003eЦе дозволяє нам забезпечити надійну та оперативну доставку вантажів з Китаю та Європи, скоротити час транзиту, ваші витрати та забезпечити високий рівень сервісу.\\u003c/p\\u003e\"},{\"_id\":\"cf-FXJS40_w_OHdlLWhaoNGT\",\"_type\":\"_\",\"name\":\"Працюємо на результат та розуміємо потреби сучасних бізнесів\",\"description\":\"\\u003cp\\u003eЗабезпечуємо повний цикл послуг з вантажоперевезень, знаходимо гнучкі рішення для досягнення поставлених задач, використовуємо мультимодальні перевезення.\\u003c/p\\u003e\"},{\"_id\":\"cf-ZGRwsJDxBtK41zbjJGVqZ\",\"_type\":\"_\",\"name\":\"Гарантуємо прозорість та економне планування вашого бюджету\",\"description\":\"\\u003cp\\u003eНадаємо індивідуальний розрахунок вартості доставки та знаходимо найефективніші рішення перевезення ваших вантажів\\u003c/p\\u003e\"},{\"_id\":\"cf-8ev_lcBr0V8606xqPxas7\",\"_type\":\"_\",\"name\":\"За вами закріплюється персональний менеджер\",\"description\":\"\\u003cp\\u003eЗ моменту першої заявки і до отримання вами вантажу — наші менеджери надають професійний супровід та кваліфіковану підтримку на кожному з етапів.\\u003c/p\\u003e\"}],\"dolphincargo_block_advantages_top_image\":93,\"dolphincargo_block_advantages_top_bootom\":97}} /-->', 'Головна', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2024-12-16 08:18:59', '2024-12-16 08:18:59', '', 10, 'http://dolphincargo.loc/?p=115', 0, 'revision', '', 0),
